module.exports = "<ion-header class=\"interior-header\" dir=\"rtl\">\n  \n  <app-page-header titleKey=\"pageHeader.common/pay-rules/pay-rules\" fallback=\"/\">\n<div page-actions><button type=\"button\" class=\"action-btn ghost\" (click)=\"showSearchbar = !showSearchbar\" title=\"جستجو\">\n        <ion-icon name=\"search-outline\"></ion-icon>\n      </button>\n</div>\n\n<div class=\"header-search-bar\" *ngIf=\"showSearchbar\">\n    <div class=\"search-input-wrap\">\n      <ion-icon name=\"search-outline\"></ion-icon>\n      <input type=\"search\" [(ngModel)]=\"queryText\" placeholder=\"جستجوی دوره، کاربرگ، پایه تحصیلی...\" (keyup.enter)=\"search()\" autofocus />\n      <button type=\"button\" class=\"action-btn primary\" (click)=\"search()\">جستجو</button>\n      <button type=\"button\" class=\"action-btn ghost\" (click)=\"onCancel()\">انصراف</button>\n    </div>\n  </div>\n  </app-page-header>\n</ion-header>\n\n<ion-content class=\"common-page-content\" dir=\"rtl\">\n  <div class=\"common-page-wrapper\">\n    <div class=\"backdrop-glows\" aria-hidden=\"true\">\n      <div class=\"glow-orb glow-purple\"></div>\n      <div class=\"glow-orb glow-amber\"></div>\n      <div class=\"glow-orb glow-emerald\"></div>\n    </div>\n\n    <!-- Playful Floating Icons -->\n    <span class=\"floating-decor pencil\" aria-hidden=\"true\">📜</span>\n    <span class=\"floating-decor star\" aria-hidden=\"true\">✦</span>\n    <span class=\"floating-decor book\" aria-hidden=\"true\">⚖️</span>\n    <span class=\"floating-decor sparkle\" aria-hidden=\"true\">✨</span>\n\n    <div class=\"content-page-card\">\n      <div class=\"content-page-header\">\n        <div class=\"header-badge\">\n          <span class=\"sparkle-icon\">✦</span>\n          <span>شفافیت و اعتماد</span>\n        </div>\n        <h1>شرایط و قوانین استفاده از اول آموز</h1>\n        <p>\n          هدف ما در اول آموز، تجربه‌ای مطمئن و رضایت‌بخش در تهیه دوره‌های روش تدریس، کاربرگ‌ها و فایل‌های آموزشی است. مطالعه این موارد حقوق دوطرفه کاربران و سامانه را تبیین می‌کند.\n        </p>\n      </div>\n\n      <div class=\"legal-content\">\n        <div class=\"legal-section\">\n          <div class=\"legal-badge-icon purple\">\n            <ion-icon name=\"shield-checkmark-outline\"></ion-icon>\n          </div>\n          <div class=\"legal-body\">\n            <h3>۱. قوانین عمومی و اعتبار خدمات</h3>\n            <p>\n              کلیه اصول و رویه‌های سامانه اول آموز منطبق با قوانین تجارت الکترونیک، قانون حمایت از حقوق مصرف‌کننده و ضوابط نشر محتوای آموزشی کشور است. استفاده و ثبت سفارش در این وبگاه به منزله آگاهی و پذیرش این قوانین می‌باشد.\n            </p>\n          </div>\n        </div>\n\n        <div class=\"legal-section\">\n          <div class=\"legal-badge-icon emerald\">\n            <ion-icon name=\"cloud-download-outline\"></ion-icon>\n          </div>\n          <div class=\"legal-body\">\n            <h3>۲. تحویل و دسترسی به فایل‌های دانلودی</h3>\n            <p>\n              بلافاصله پس از تکمیل فرایند پرداخت در درگاه بانکی، لینک دانلود کاربرگ‌ها، طرح‌درس‌ها و دسترسی به ویدیوهای دوره‌های آموزشی در پنل کاربری خریدار فعال می‌گردد و به صورت نامحدود در دسترس خواهد بود.\n            </p>\n          </div>\n        </div>\n\n        <div class=\"legal-section\">\n          <div class=\"legal-badge-icon amber\">\n            <ion-icon name=\"lock-closed-outline\"></ion-icon>\n          </div>\n          <div class=\"legal-body\">\n            <h3>۳. مالکیت معنوی و حقوق مولفین</h3>\n            <p>\n              تمامی محتواهای آموزشی، ویدیوهای روش تدریس، تمرینات و کاربرگ‌های ارائه شده در اول آموز متعلق به مدرسان و این سامانه است. هرگونه انتشار تجاری، کپی یا بارگذاری در کانال‌ها و سایت‌های دیگر بدون اجازه کتبی پیگرد قانونی دارد.\n            </p>\n          </div>\n        </div>\n\n        <div class=\"legal-section\">\n          <div class=\"legal-badge-icon rose\">\n            <ion-icon name=\"card-outline\"></ion-icon>\n          </div>\n          <div class=\"legal-body\">\n            <h3>۴. سیاست بازگشت وجه و ضمانت رضایت</h3>\n            <p>\n              در صورت وجود هرگونه مشکل فنی در پخش ویدیوها یا عدم دانلود فایل‌ها که از سوی پشتیبانی اول آموز قابل رفع نباشد، وجه پرداختی کاربر طی ۲۴ الی ۴۸ ساعت کاری مسترد خواهد شد.\n            </p>\n          </div>\n        </div>\n\n        <div class=\"legal-section\">\n          <div class=\"legal-badge-icon purple\">\n            <ion-icon name=\"call-outline\"></ion-icon>\n          </div>\n          <div class=\"legal-body\">\n            <h3>۵. راه‌های پشتیبانی و ثبت شکایات</h3>\n            <p>\n              آموزگاران گرامی می‌توانند در صورت داشتن هرگونه ابهام، انتقاد یا سوال از طریق شماره تلفن <b>۰۹۳۹۴۱۳۴۳۸۷</b>، ارسال پیام در صفحه پشتیبانی یا ایمیل <b>info@avalamuz.ir</b> اقدام نمایند.\n            </p>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"suggestion-box\" style=\"margin-top: 36px;\">\n        <div class=\"suggestion-title\">\n          <span class=\"sparkle-icon\">✦</span>\n          <span>صفحات مرتبط:</span>\n        </div>\n        <div class=\"suggestion-chips\">\n          <a class=\"chip-link\" routerLink=\"/PrivacyPolicy\">\n            <ion-icon name=\"eye-off-outline\"></ion-icon>\n            <span>سیاست حفظ حریم خصوصی</span>\n          </a>\n          <a class=\"chip-link\" routerLink=\"/About\">\n            <ion-icon name=\"information-circle-outline\"></ion-icon>\n            <span>درباره اول آموز</span>\n          </a>\n          <a class=\"chip-link\" routerLink=\"/Suport\">\n            <ion-icon name=\"chatbubbles-outline\"></ion-icon>\n            <span>ارتباط با پشتیبانی</span>\n          </a>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <app-footer></app-footer>\n</ion-content>\n";

